/* ============================================================================
   eCOB Bridge Hub — SHARED DATA LAYER (loaded by every page)
   ─────────────────────────────────────────────────────────────
   UPDATE METRICS HERE:
     1. Keep the header row: month,productivity,prod_count,quality,attendance
     2. One row per month, in order. `productivity`, `quality` and `attendance`
        are percents (no % sign), `prod_count` is a whole number (no commas).
     3. Update `refreshed` in ECOB_META, save, redeploy.
     4. KPI goals live in ECOB_META.goals — any value below its
        goal is automatically highlighted in amber.
   ========================================================================== */
var ECOB_META = {
  program: "Payment Integrity — eCOB Operations",
  refreshed: "Nov 14, 2026 · 6:00 AM ET",
  // Optional announcement banner — set to a string to show it, "" to hide.
  announcement: "",
  // KPI goals — a value below its goal is highlighted in amber.
  goals: { productivity: 100, quality: 98, attendance: 90 }
};

var METRICS_CSV = `month,productivity,prod_count,quality,attendance
Jan,125.82,34181,98.44,97.65
Feb,52.15,21462,97.33,97.52
Mar,112.81,42781,98.71,97.00
Apr,111.65,36646,98.35,98.33
May,115.29,32701,98.68,98.30
Jun,120.08,40172,98.94,98.08
Jul,122.47,39475,98.87,97.83
Aug,132.40,48125,98.87,98.66
Sep,133.18,39920,99.02,98.38
Oct,124.04,41123,99.13,98.37`;

/* ============================================================================
   DAILY INVENTORY — day-to-day backlog counts starting November.
   Format per line: date,count   (add one row per business day)
   ========================================================================== */
var INVENTORY_CSV = `date,count
Nov 1,2841
Nov 2,2768
Nov 3,2902
Nov 4,2855
Nov 5,3011
Nov 6,2977
Nov 7,2890
Nov 8,2834
Nov 9,2922
Nov 10,2878
Nov 11,2945
Nov 12,2861
Nov 13,2799
Nov 14,2753`;

/* ---- Admin overrides: the admin.html editor writes localStorage overrides;
   they merge over the file defaults so both pages see edited values. ---- */
try {
  var _ovMeta = localStorage.getItem('ecob-admin-meta');
  if (_ovMeta) {
    var _om = JSON.parse(_ovMeta);
    ['program', 'refreshed', 'announcement'].forEach(function (k) { if (_om[k] !== undefined) ECOB_META[k] = _om[k]; });
    if (_om.goals) Object.keys(_om.goals).forEach(function (k) { if (_om.goals[k] != null && !isNaN(+_om.goals[k])) ECOB_META.goals[k] = +_om.goals[k]; });
  }
  var _ovCsv = localStorage.getItem('ecob-admin-csv');
  if (_ovCsv && /month,productivity/i.test(_ovCsv)) METRICS_CSV = _ovCsv;
  var _ovInv = localStorage.getItem('ecob-admin-inv');
  if (_ovInv && /date,count/i.test(_ovInv)) INVENTORY_CSV = _ovInv;
} catch (e) { /* localStorage unavailable — keep file defaults */ }

